// Open wetland silhouettes remain readable at Fit; fine rushes come from art.
// The pool field is world seeded and baked once, never regenerated by zoom.
export function paintWetlandPools({ map, pixel, width, height, detail, regionIds, land, dryDistance,
  colours, waterIndices, waterBase, waterStrength, noise, mixColour, surfaces = null, protectedCentres = null }) {
  const centres = protectedCentres ?? map.regions.map(r => pixel(r.centre));
  const stats = { pools: 0, margins: 0, illustratedBanks: 0 };
  for (let y = 2; y < height - 2; y++) for (let x = 2; x < width - 2; x++) {
    const i = y * width + x, region = map.regions[regionIds[i]];
    if (!region || region.biome !== 'swamp' || !land[i] || waterIndices[i] || dryDistance[i] < 14) continue;
    // Preserve dry approaches around fixtures and a margin for border banks.
    if ([i - 8, i + 8, i - width * 8, i + width * 8].some(j => regionIds[j] !== regionIds[i])) continue;
    const broad = noise(map.seed ^ 51991, x, y * 1.6, 29 * detail);
    const fine = noise(map.seed ^ 9713, x, y, 8 * detail);
    const approach = centres.reduce((d, p) => Math.min(d, Math.hypot(x - p.x, y - p.y)), Infinity);
    const field = broad * .8 + fine * .2 - .28 * Math.exp(-((approach / (12 * detail)) ** 2));
    if (field > .61) {
      const depth = Math.min(1, (field - .61) * 6);
      const base = mixColour(0x6a687b, 0x434858, depth);
      const phase = ((x + Math.floor(y * .4)) % 8 + 8) % 8;
      waterIndices[i] = 48 + phase; waterBase[i] = base; waterStrength[i] = 18;
      colours[i] = mixColour(base, 0xaaa1b2, fine > .65 ? .24 : .07);
      stats.pools++;
    } else if (field > .55) {
      colours[i] = mixColour(colours[i], fine > .5 ? 0x998b9e : 0x514854, .58);
      stats.margins++;
    }
  }
  if (surfaces && stats.pools) {
    const cap = 36 * detail, wet = new Uint16Array(width * height), dry = new Uint16Array(width * height);
    const pool = i => land[i] && map.regions[regionIds[i]]?.biome === 'swamp' && waterIndices[i] >= 48 && waterIndices[i] <= 55;
    for (let i = 0; i < wet.length; i++) { wet[i] = pool(i) ? cap : 0; dry[i] = pool(i) ? 0 : cap; }
    for (const field of [wet, dry]) {
      for (let y = 0; y < height; y++) for (let x = 0; x < width; x++) {
        const i = y * width + x;
        field[i] = Math.min(field[i], x ? field[i - 1] + 3 : cap, y ? field[i - width] + 3 : cap);
      }
      for (let y = height - 1; y >= 0; y--) for (let x = width - 1; x >= 0; x--) {
        const i = y * width + x;
        field[i] = Math.min(field[i], x < width - 1 ? field[i + 1] + 3 : cap, y < height - 1 ? field[i + width] + 3 : cap);
      }
    }
    for (let y = 1; y < height - 1; y++) for (let x = 1; x < width - 1; x++) {
      const i = y * width + x;
      if (!land[i] || map.regions[regionIds[i]]?.biome !== 'swamp') continue;
      const submerged = pool(i), field = submerged ? wet : dry, d = field[i] / 3;
      const reach = (submerged ? 5 : 8) * detail;
      if (d >= reach || (!submerged && waterIndices[i])) continue;
      const horizontal = Math.abs(field[i + 1] - field[i - 1]) < Math.abs(field[i + width] - field[i - width]);
      const depth = submerged ? .53 + .42 * d / reach : .46 * (1 - d / reach);
      const colour = surfaces.bank('swamp', x, y, depth, horizontal);
      const feather = Math.pow(1 - d / reach, .7) * .86;
      if (submerged) waterBase[i] = mixColour(waterBase[i], colour, feather * .7);
      else colours[i] = mixColour(colours[i], colour, feather);
      stats.illustratedBanks++;
    }
  }
  return stats;
}
